INSERT OR IGNORE INTO wiki_articles(pet_type_id,breed_id,category_id,title,summary,content,image_url,source_type,source_name,source_url,source_external_id,content_hash,crawled_at,status,created_at,updated_at) VALUES (1,NULL,2,'Chế độ ăn cơ bản cho chó','Chó trưởng thành thường ăn 2 bữa mỗi ngày; chó con cần nhiều bữa nhỏ hơn. Chọn thức ăn hoàn chỉnh phù hợp độ tuổi và cỡ giống, luôn để sẵn nước sạch.','Chó trưởng thành thường ăn 2 bữa mỗi ngày; chó con cần nhiều bữa nhỏ hơn. Chọn thức ăn hoàn chỉnh phù hợp độ tuổi và cỡ giống, luôn để sẵn nước sạch.' || char(10) || '' || char(10) || 'Không cho chó ăn socola, nho hoặc nho khô, hành, tỏi, và các sản phẩm chứa xylitol (chất tạo ngọt) vì có thể gây ngộ độc. Tránh xương nấu chín vì dễ vỡ thành mảnh sắc.' || char(10) || '' || char(10) || 'Khi đổi loại thức ăn, hãy trộn dần trong khoảng 7-10 ngày để tránh rối loạn tiêu hóa.' || char(10) || '' || char(10) || 'Lưu ý: thông tin mang tính tham khảo chung, không thay thế tư vấn của bác sĩ thú y.',NULL,'ORIGINAL','App Pet',NULL,'orig:01',NULL,NULL,'PUBLISHED',datetime('now','localtime'),datetime('now','localtime'));
INSERT OR IGNORE INTO wiki_articles(pet_type_id,breed_id,category_id,title,summary,content,image_url,source_type,source_name,source_url,source_external_id,content_hash,crawled_at,status,created_at,updated_at) VALUES (1,NULL,3,'Chăm sóc sức khỏe định kỳ cho chó','Tiêm phòng, tẩy giun và phòng ve, bọ chét theo lịch do bác sĩ thú y tư vấn. Nên khám tổng quát ít nhất mỗi năm một lần.','Tiêm phòng, tẩy giun và phòng ve, bọ chét theo lịch do bác sĩ thú y tư vấn. Nên khám tổng quát ít nhất mỗi năm một lần.' || char(10) || '' || char(10) || 'Hãy đưa chó đi khám sớm nếu thấy bỏ ăn hơn 24 giờ, nôn hoặc tiêu chảy kéo dài, khó thở, đi lại khó khăn, hoặc lờ đờ bất thường. Đánh răng và kiểm tra tai, móng thường xuyên giúp phát hiện vấn đề sớm.' || char(10) || '' || char(10) || 'Lưu ý: thông tin mang tính tham khảo chung, không thay thế tư vấn của bác sĩ thú y.',NULL,'ORIGINAL','App Pet',NULL,'orig:02',NULL,NULL,'PUBLISHED',datetime('now','localtime'),datetime('now','localtime'));
INSERT OR IGNORE INTO wiki_articles(pet_type_id,breed_id,category_id,title,summary,content,image_url,source_type,source_name,source_url,source_external_id,content_hash,crawled_at,status,created_at,updated_at) VALUES (2,NULL,2,'Chế độ ăn cơ bản cho mèo','Mèo là loài ăn thịt bắt buộc và cần một số dưỡng chất như taurine, vì vậy nên dùng thức ăn hoàn chỉnh dành riêng cho mèo, không thay bằng thức ăn của chó trong thời gian dài.','Mèo là loài ăn thịt bắt buộc và cần một số dưỡng chất như taurine, vì vậy nên dùng thức ăn hoàn chỉnh dành riêng cho mèo, không thay bằng thức ăn của chó trong thời gian dài.' || char(10) || '' || char(10) || 'Thức ăn ướt giúp mèo bổ sung nước. Luôn có nước sạch. Tránh hành, tỏi, socola, nho. Nhiều mèo trưởng thành không dung nạp lactose nên sữa bò có thể gây tiêu chảy.' || char(10) || '' || char(10) || 'Lưu ý: thông tin mang tính tham khảo chung, không thay thế tư vấn của bác sĩ thú y.',NULL,'ORIGINAL','App Pet',NULL,'orig:03',NULL,NULL,'PUBLISHED',datetime('now','localtime'),datetime('now','localtime'));
INSERT OR IGNORE INTO wiki_articles(pet_type_id,breed_id,category_id,title,summary,content,image_url,source_type,source_name,source_url,source_external_id,content_hash,crawled_at,status,created_at,updated_at) VALUES (2,NULL,3,'Dấu hiệu cần đưa mèo đi khám','Tiêm phòng, tẩy giun và khám định kỳ theo tư vấn của bác sĩ thú y. Giữ khay cát sạch và theo dõi thói quen đi vệ sinh.','Tiêm phòng, tẩy giun và khám định kỳ theo tư vấn của bác sĩ thú y. Giữ khay cát sạch và theo dõi thói quen đi vệ sinh.' || char(10) || '' || char(10) || 'Mèo bỏ ăn hơn 24 giờ cần được khám sớm. Mèo đực cố đi tiểu nhưng không ra nước tiểu là tình trạng cấp cứu, cần đến phòng khám ngay.' || char(10) || '' || char(10) || 'Lưu ý: thông tin mang tính tham khảo chung, không thay thế tư vấn của bác sĩ thú y.',NULL,'ORIGINAL','App Pet',NULL,'orig:04',NULL,NULL,'PUBLISHED',datetime('now','localtime'),datetime('now','localtime'));
INSERT OR IGNORE INTO wiki_articles(pet_type_id,breed_id,category_id,title,summary,content,image_url,source_type,source_name,source_url,source_external_id,content_hash,crawled_at,status,created_at,updated_at) VALUES (3,NULL,2,'Chế độ ăn cơ bản cho chim cảnh','Nên kết hợp hỗn hợp hạt chất lượng, thức ăn viên (pellet) và rau củ tươi rửa sạch. Thay nước mỗi ngày.','Nên kết hợp hỗn hợp hạt chất lượng, thức ăn viên (pellet) và rau củ tươi rửa sạch. Thay nước mỗi ngày.' || char(10) || '' || char(10) || 'Tuyệt đối không cho chim ăn bơ (avocado), socola, đồ có caffeine, thức ăn mặn, hành và tỏi.' || char(10) || '' || char(10) || 'Lưu ý: thông tin mang tính tham khảo chung, không thay thế tư vấn của bác sĩ thú y.',NULL,'ORIGINAL','App Pet',NULL,'orig:05',NULL,NULL,'PUBLISHED',datetime('now','localtime'),datetime('now','localtime'));
INSERT OR IGNORE INTO wiki_articles(pet_type_id,breed_id,category_id,title,summary,content,image_url,source_type,source_name,source_url,source_external_id,content_hash,crawled_at,status,created_at,updated_at) VALUES (3,NULL,3,'Môi trường và sức khỏe của chim','Đặt lồng nơi thoáng, tránh gió lùa và nắng gắt. Khói và hơi từ chảo chống dính (PTFE/Teflon) rất độc với chim, hãy tránh xa khu bếp khi nấu ăn.','Đặt lồng nơi thoáng, tránh gió lùa và nắng gắt. Khói và hơi từ chảo chống dính (PTFE/Teflon) rất độc với chim, hãy tránh xa khu bếp khi nấu ăn.' || char(10) || '' || char(10) || 'Chim xù lông, ngồi dưới đáy lồng, bỏ ăn hoặc thở há miệng là dấu hiệu bệnh; nên đưa đến bác sĩ có kinh nghiệm về chim.' || char(10) || '' || char(10) || 'Lưu ý: thông tin mang tính tham khảo chung, không thay thế tư vấn của bác sĩ thú y.',NULL,'ORIGINAL','App Pet',NULL,'orig:06',NULL,NULL,'PUBLISHED',datetime('now','localtime'),datetime('now','localtime'));
INSERT OR IGNORE INTO wiki_articles(pet_type_id,breed_id,category_id,title,summary,content,image_url,source_type,source_name,source_url,source_external_id,content_hash,crawled_at,status,created_at,updated_at) VALUES (4,NULL,2,'Cho cá ăn đúng cách','Cho ăn lượng nhỏ, 1-2 lần mỗi ngày, lượng cá ăn hết trong vài phút. Thức ăn thừa làm bẩn nước và là nguyên nhân phổ biến gây bệnh.','Cho ăn lượng nhỏ, 1-2 lần mỗi ngày, lượng cá ăn hết trong vài phút. Thức ăn thừa làm bẩn nước và là nguyên nhân phổ biến gây bệnh.' || char(10) || '' || char(10) || 'Chọn thức ăn phù hợp từng loài, ví dụ cá Betta cần thức ăn giàu đạm.' || char(10) || '' || char(10) || 'Lưu ý: thông tin mang tính tham khảo chung, không thay thế tư vấn của bác sĩ thú y.',NULL,'ORIGINAL','App Pet',NULL,'orig:07',NULL,NULL,'PUBLISHED',datetime('now','localtime'),datetime('now','localtime'));
INSERT OR IGNORE INTO wiki_articles(pet_type_id,breed_id,category_id,title,summary,content,image_url,source_type,source_name,source_url,source_external_id,content_hash,crawled_at,status,created_at,updated_at) VALUES (4,NULL,6,'Giữ nước bể cá luôn ổn định','Bể mới cần thời gian để hệ vi sinh xử lý chất thải hình thành (chu trình nitơ) trước khi thả nhiều cá. Thay khoảng 20-30% nước định kỳ, dùng nước đã khử clo.','Bể mới cần thời gian để hệ vi sinh xử lý chất thải hình thành (chu trình nitơ) trước khi thả nhiều cá. Thay khoảng 20-30% nước định kỳ, dùng nước đã khử clo.' || char(10) || '' || char(10) || 'Không nuôi quá đông. Cá Betta đực nên nuôi riêng; cá vàng cần bể rộng và hệ thống lọc tốt.' || char(10) || '' || char(10) || 'Lưu ý: thông tin mang tính tham khảo chung, không thay thế tư vấn của bác sĩ thú y.',NULL,'ORIGINAL','App Pet',NULL,'orig:08',NULL,NULL,'PUBLISHED',datetime('now','localtime'),datetime('now','localtime'));
INSERT OR IGNORE INTO wiki_articles(pet_type_id,breed_id,category_id,title,summary,content,image_url,source_type,source_name,source_url,source_external_id,content_hash,crawled_at,status,created_at,updated_at) VALUES (5,NULL,2,'Chế độ ăn cơ bản cho thỏ','Cỏ khô nên chiếm phần lớn khẩu phần mỗi ngày, bổ sung rau xanh và một lượng nhỏ thức ăn viên. Răng thỏ mọc liên tục nên cần nhai cỏ khô để mài răng.','Cỏ khô nên chiếm phần lớn khẩu phần mỗi ngày, bổ sung rau xanh và một lượng nhỏ thức ăn viên. Răng thỏ mọc liên tục nên cần nhai cỏ khô để mài răng.' || char(10) || '' || char(10) || 'Hạn chế trái cây và cà rốt vì nhiều đường. Luôn có nước sạch.' || char(10) || '' || char(10) || 'Lưu ý: thông tin mang tính tham khảo chung, không thay thế tư vấn của bác sĩ thú y.',NULL,'ORIGINAL','App Pet',NULL,'orig:09',NULL,NULL,'PUBLISHED',datetime('now','localtime'),datetime('now','localtime'));
INSERT OR IGNORE INTO wiki_articles(pet_type_id,breed_id,category_id,title,summary,content,image_url,source_type,source_name,source_url,source_external_id,content_hash,crawled_at,status,created_at,updated_at) VALUES (5,NULL,3,'Khi nào cần đưa thỏ đi khám','Giữ chuồng khô, sạch và thoáng; không tắm thỏ bằng nước. Theo dõi lượng ăn và phân mỗi ngày.','Giữ chuồng khô, sạch và thoáng; không tắm thỏ bằng nước. Theo dõi lượng ăn và phân mỗi ngày.' || char(10) || '' || char(10) || 'Thỏ ngừng ăn hoặc không đi phân trong khoảng 12 giờ có thể là ngưng tiêu hóa, tình trạng nguy hiểm cần đi khám ngay.' || char(10) || '' || char(10) || 'Lưu ý: thông tin mang tính tham khảo chung, không thay thế tư vấn của bác sĩ thú y.',NULL,'ORIGINAL','App Pet',NULL,'orig:10',NULL,NULL,'PUBLISHED',datetime('now','localtime'),datetime('now','localtime'));
